library(shiny)

# -----------------------------
# WORD LIST
# -----------------------------
words <- c(
  "AUDIT",
  "LOANS",
  "DEBIT",
  "SALES",
  "FUNDS",
  "DEBTS"
)

# -----------------------------
# GET WORD OF THE DAY
# -----------------------------
get_word_of_day <- function() {

  # Use today's date
  today <- as.Date(Sys.Date())

  # Convert date to a number
  day_number <- as.integer(today)

  # Cycle through the word list
  index <- (day_number %% length(words)) + 1

  words[index]
}

# -----------------------------
# UI
# -----------------------------
ui <- fluidPage(

  titlePanel("🧙 QFR Wordle"),

  p("Guess the 5-letter finance word in 5 tries."),
  p("🟩 Green = Correct letter in correct position"),
  p("🟨 Yellow = Letter exists but in wrong position"),
  p("⬜ Gray = Letter not in the word"),

  textInput(
    "guess",
    "Enter a 5-letter word:",
    ""
  ),

  actionButton("submit", "Guess"),

  br(), br(),

  uiOutput("board"),

  br(),

  h3(textOutput("message"))

)

# -----------------------------
# SERVER
# -----------------------------
server <- function(input, output, session) {

  # Everyone gets the same word for today's date
  target <- get_word_of_day()

  guesses <- reactiveVal(character())

  colours <- reactiveVal(list())

  observeEvent(input$submit, {

    if (length(guesses()) >= 5)
      return()

    guess <- toupper(trimws(input$guess))

    if (nchar(guess) != 5) {

      showNotification(
        "Please enter exactly 5 letters.",
        type = "error"
      )

      return()
    }

    g <- strsplit(guess, "")[[1]]
    t <- strsplit(target, "")[[1]]

    cols <- rep("#BDBDBD", 5)

    # -----------------------------
    # GREEN - correct position
    # -----------------------------
    for (i in 1:5) {

      if (g[i] == t[i]) {
        cols[i] <- "#4CAF50"
      }

    }

    # -----------------------------
    # YELLOW - correct letter,
    # wrong position
    # -----------------------------
    for (i in 1:5) {

      if (cols[i] != "#4CAF50") {

        if (g[i] %in% t) {
          cols[i] <- "#FBC02D"
        }

      }

    }

    guesses(c(guesses(), guess))

    tmp <- colours()
    tmp[[length(tmp) + 1]] <- cols
    colours(tmp)

    updateTextInput(
      session,
      "guess",
      value = ""
    )

  })

  # -----------------------------
  # GAME BOARD
  # -----------------------------
  output$board <- renderUI({

    rows <- list()

    g <- guesses()
    c <- colours()

    for (i in 1:5) {

      if (i <= length(g)) {

        letters <- strsplit(g[i], "")[[1]]
        cols <- c[[i]]

      } else {

        letters <- rep("", 5)
        cols <- rep("white", 5)

      }

      boxes <- lapply(1:5, function(j) {

        div(
          style = paste0(
            "display:inline-block;",
            "width:55px;",
            "height:55px;",
            "line-height:55px;",
            "margin:4px;",
            "border:2px solid black;",
            "background:", cols[j], ";",
            "font-size:28px;",
            "font-weight:bold;",
            "text-align:center;"
          ),
          letters[j]
        )

      })

      rows[[i]] <- div(boxes)

    }

    do.call(tagList, rows)

  })

  # -----------------------------
  # MESSAGE
  # -----------------------------
  output$message <- renderText({

    if (any(guesses() == target)) {

      return(
        "🎉 Congratulations, you are a wizard at this!"
      )

    }

    if (length(guesses()) >= 5) {

      return(
        paste(
          "🍀 Better luck tomorrow! The word was",
          target
        )
      )

    }

    paste(
      "Attempts:",
      length(guesses()),
      "/5"
    )

  })

}

# -----------------------------
# RUN APP
# -----------------------------
shinyApp(
  ui = ui,
  server = server
)

